def total(order: Order): Money =
  if !isValid(order) then Money.zero
  else discounted(subtotal(order), order.discount)

private def isValid(order: Order): Boolean =
  order.lines.nonEmpty

private def subtotal(order: Order): Money =
  order.lines.map(_.amount).sum

private def discounted(total: Money, discount: Discount): Money =
  total - discount
